  check('侦查未接战（无损兵）', (cS.army.yibing || 0) === beforeY + 500, '兵力 ' + cS.army.yibing);
  check('侦查回报守军情报', !!(rScout.intel && rScout.intel.length), (rScout.intel || []).join(' / '));
