    var eqYw = DATA.EQUIP.yt_sword.yw || 0;
    /* 合计口径：攻值 = (基础勇武 + 装备勇武) × 10 + 装备攻击 */
    return a.atkVal === (g.yw + eqYw) * G.ATK_PER_YW + a.atk
