    s.res.grain = 1e8; s.res.wood = 1e8; s.res.stone = 1e8; s.res.iron = 1e8;
    var i = -1;
    for (var k = 0; k < c.cells.length; k++) { if (!c.official && !c.cells[k].build && !c.cells[k].pending) { i = k; break; } }
    if (i < 0) return true;
