    while (s.queues.build.length && guard++ < 10) { var q = s.queues.build[0]; q.elapsed = q.totalTime; G.applyBuildDone(q); var ix = s.queues.build.indexOf(q); if (ix >= 0) s.queues.build.splice(ix, 1); }
