    var want = (DATA.EQUIP.yt_helm.sta || 0) + (DATA.EQUIP.yt_neck.sta || 0)
      + (DATA.EQUIP.yt_should.sta || 0) + (DATA.SETS.yitian.eff[3].sta || 0);
