  console.log('\n===== 51. v67：放弃城池 + 关联数据清理 + 侧栏分列 =====');
  function rd67(f) { return fsMod.readFileSync(pathMod.join(__dirname, 'js', f + '.js'), 'utf8'); }
  var dmS67 = rd67('domain'), uS67 = rd67('ui'), mS67 = rd67('main');
