    /* 复原：新造的件收回，等级归零 */
    S77e.res.gold = bkGold; S77e.res.iron = bkIron; S77e.res.stone = bkStone;
    if (inst77 && typeof inst77 === 'object') inst77.enh = 0;
    if (added77) { var gi77 = S77e.inventory.indexOf(inst77); if (gi77 >= 0) S77e.inventory.splice(gi77, 1); }
