      g.equip = { weapon: y };
      var by = G.systems.genEquipBonus(g);
      g.equip = bk;
      [x, y].forEach(function (it) { var i = st64.inventory.indexOf(it); if (i >= 0) st64.inventory.splice(i, 1); });
      return bx.atk > by.atk;
