      G.ui._trainFilter = 'normal';
      G.ui._trainBIdx = null;
      G.ui._trainTab = 'inf';
      var inf = G.ui.troopsHTML();
      G.ui._trainTab = 'que';
      var que = G.ui.troopsHTML();
      ok = inf.indexOf('本营募兵队列') < 0 && inf.indexOf('id="train-count"') >= 0
