    rec8.fills.length = 0;
    GAME.map.render(fake8, { vx: site8.x, vy: site8.y, spanX: 13, spanY: 11, cell: 63 });
    var n1 = cnt8();
    wst8.d[key8] = 1;                                   /* 已探 → 星也要消失 */
    rec8.fills.length = 0;
    GAME.map.render(fake8, { vx: site8.x, vy: site8.y, spanX: 13, spanY: 11, cell: 63 });
    var n2 = cnt8();
